    pricingText: "Phí dịch vụ sự kiện thay đổi tùy theo sự kiện, thời gian xếp hàng, giới hạn mua hàng và giá trị sản phẩm. Chúng tôi không công bố mức giá cố định cho sự kiện vì mỗi tình huống đều khác nhau. Hãy liên hệ trực tiếp để nhận báo giá rõ ràng, trung thực.",
