export const translations = { en, fr, ja, es, it, de, ko, zh, pt, id, vi, nl };

export const SUPPORTED_LANGS = Object.keys(translations);

export const LANG_LABELS = {
  en: "English", fr: "Français", ja: "日本語", es: "Español", it: "Italiano",
  de: "Deutsch", ko: "한국어", zh: "中文", pt: "Português", id: "Indonesia",
  vi: "Tiếng Việt", nl: "Nederlands",
};

export function detectLang(candidates = []) {
  for (const raw of candidates) {
    if (!raw) continue;
    const code = String(raw).slice(0, 2).toLowerCase();
    if (SUPPORTED_LANGS.includes(code)) return code;
  }
  return "en";
}

/** Default export kept for any code that still imports the English copy directly */
export const copy = en;
export const t = en;
export type Lang = keyof typeof translations;
export type T = Copy;
